# O(Q) for Q(c,d)=c.d on F2^{2k} as permutations of points (generated by orthogonal transvections).
import numpy as np
from bell import popc
def oq_perms(k):
    n=4**k; z=np.arange(n); msk=(1<<k)-1
    Q=lambda x: popc((x&msk)&(x>>k))&1
    def B(x,y): return (popc(((x&msk)&(y>>k)) ^ ((y&msk)&(x>>k))) &1)
    gens=[]
    for v in range(1,n):
        if Q(np.array([v]))[0]==1:
            gens.append(z ^ (B(z,np.full(n,v))*v))
    gens=np.array(gens)
    # closure by BFS on permutations (as tuples)
    seen={z.tobytes()}; frontier=[z]; allp=[z]
    while frontier:
        nf=[]
        for p in frontier:
            for g in gens:
                h=g[p]; t=h.tobytes()
                if t not in seen: seen.add(t); nf.append(h); allp.append(h)
        frontier=nf
    return np.array(allp)
if __name__=='__main__':
    import sys
    k=int(sys.argv[1]); P=oq_perms(k); print(len(P))
